cd /home/user/rork-app

# ITEM 1: Soak test status
echo "=== ITEM 1: SOAK TEST ==="
SOAK_PID=$(cat /tmp/ivx-soak-pid.txt 2>/dev/null)
if [ -n "$SOAK_PID" ] && kill -0 $SOAK_PID 2>/dev/null; then
  echo "STATUS=RUNNING"
  echo "PID=$SOAK_PID"
  cat /tmp/ivx-soak-results.json 2>/dev/null | bun -e '
    try {
      const d = JSON.parse(require("fs").readFileSync("/dev/stdin","utf8"));
      const elapsed = ((d.lastUpdate || Date.now()) - d.startTime) / 60000;
      console.log("ELAPSED_MIN=" + elapsed.toFixed(1));
      console.log("REMAINING_MIN=" + (120 - elapsed).toFixed(1));
      console.log("REQUESTS=" + d.totalRequests);
      console.log("PASS=" + d.passCount);
      console.log("FAIL=" + d.failCount);
      console.log("COLD_START_502=" + (d.coldStart502s ?? 0));
      console.log("TIMEOUTS=" + (d.timeouts ?? 0));
      console.log("RESTARTS=" + (d.restarts ?? 0));
      console.log("SHA_MISMATCHES=" + (d.shaMismatches ?? 0));
      console.log("DB_FAILURES=" + (d.dbFailures ?? 0));
      console.log("PROVIDER_FAILURES=" + (d.providerFailures ?? 0));
      console.log("P50=" + d.p50LatencyMs);
      console.log("P95=" + d.p95LatencyMs);
      console.log("MAX_LATENCY=" + d.maxLatencyMs);
      console.log("BASELINE_SHA=" + (d.productionSha ?? "N/A").slice(0, 12));
      // Check sample gaps
      if (d.samples && d.samples.length > 1) {
        let maxGap = 0;
        for (let i = 1; i < d.samples.length; i++) {
          const gap = d.samples[i].timestamp - d.samples[i-1].timestamp;
          if (gap > maxGap) maxGap = gap;
        }
        console.log("MAX_SAMPLE_GAP_SEC=" + (maxGap/1000).toFixed(1));
        console.log("SAMPLE_COUNT=" + d.samples.length);
      }
    } catch(e) { console.log("ERROR=" + e.message); }
  '
else
  echo "STATUS=NOT_RUNNING"
fi

echo ""
echo "=== ITEM 2: SECRET BINDING ==="
# Check env var presence in multiple contexts
echo "SHELL_ENV:"
bun -e 'console.log("IVX_AI_SYSTEM_SECRET=" + (process.env.IVX_AI_SYSTEM_SECRET ? "PRESENT" : "ABSENT"))' 2>/dev/null
echo "PROC_ENV:"
grep -o 'IVX_AI_SYSTEM_SECRET=[^ ]*' /proc/self/environ 2>/dev/null || echo "NOT_IN_PROC_ENV"
echo "PRODUCTION_HEALTH:"
curl -s -m 15 https://api.ivxholding.com/health 2>/dev/null | bun -e '
  try {
    const d = JSON.parse(require("fs").readFileSync("/dev/stdin","utf8"));
    console.log("status=" + d.status);
    console.log("ai=" + (d.ai?.ok ?? "N/A"));
    console.log("ai_model=" + (d.ai?.model ?? "N/A"));
    console.log("ai_error=" + (d.ai?.error ?? "none"));
    console.log("databaseConfigured=" + d.databaseConfigured);
  } catch(e) { console.log("ERROR=" + e.message); }
' 2>/dev/null

# Check if the secret is used in code and how
echo ""
echo "CODE_USAGE:"
grep -rn 'IVX_AI_SYSTEM_SECRET' backend/ --include='*.ts' 2>/dev/null | head -20
grep -rn 'X-IVX-System-Key' backend/ --include='*.ts' 2>/dev/null | head -20

