cd /home/user/rork-app

# ITEM 2: Deep investigation of IVX_AI_SYSTEM_SECRET
# Check what actually happens when we try to use the system key path in production
echo "=== ITEM 2: SECRET BINDING INVESTIGATION ==="

# Test 1: Does production AI work without the system secret?
echo "--- Test 1: Public chat (no system key needed) ---"
curl -s -m 30 -X POST https://api.ivxholding.com/public/chat \
  -H 'Content-Type: application/json' \
  -d '{"message":"hello"}' 2>/dev/null | bun -e '
  try {
    const d = JSON.parse(require("fs").readFileSync("/dev/stdin","utf8"));
    console.log("STATUS=" + (d.ok ? "OK" : "FAIL"));
    console.log("MODEL=" + (d.model ?? "N/A"));
    console.log("ANSWER_LENGTH=" + (d.answer ?? "").length);
  } catch(e) { console.log("ERROR=" + e.message); }
'

echo ""
echo "--- Test 2: System key auth path (no key) ---"
curl -s -m 15 -o /dev/null -w 'HTTP_STATUS=%{http_code}' https://api.ivxholding.com/api/ivx/senior-developer/worker/status 2>/dev/null
echo ""

echo ""
echo "--- Test 3: System key with empty value ---"
curl -s -m 15 -o /dev/null -w 'HTTP_STATUS=%{http_code}' -H 'X-IVX-System-Key: ' https://api.ivxholding.com/api/ivx/senior-developer/worker/status 2>/dev/null
echo ""

echo ""
echo "--- Test 4: Check all env vars in production via /health ---"
curl -s -m 15 https://api.ivxholding.com/health 2>/dev/null | bun -e '
  try {
    const d = JSON.parse(require("fs").readFileSync("/dev/stdin","utf8"));
    console.log("status=" + d.status);
    console.log("ai.ok=" + (d.ai?.ok ?? "N/A"));
    console.log("ai.model=" + (d.ai?.model ?? "N/A"));
    console.log("databaseConfigured=" + d.databaseConfigured);
    console.log("queue.depth=" + (d.queue?.depth ?? "N/A"));
    console.log("seniorDev.enabled=" + (d.seniorDeveloper?.enabled ?? "N/A"));
    console.log("commit=" + (d.commit ?? "N/A").slice(0,12));
  } catch(e) { console.log("ERROR=" + e.message); }
'

echo ""
echo "--- Test 5: Check /version ---"
curl -s -m 15 https://api.ivxholding.com/version 2>/dev/null | bun -e '
  try {
    const d = JSON.parse(require("fs").readFileSync("/dev/stdin","utf8"));
    console.log("ok=" + d.ok);
    console.log("commit=" + (d.commit ?? "N/A").slice(0,12));
    console.log("deploymentMarker=" + (d.deploymentMarker ?? "N/A"));
  } catch(e) { console.log("ERROR=" + e.message); }
'

echo ""
echo "--- Test 6: Credential status endpoint (if accessible) ---"
curl -s -m 15 https://api.ivxholding.com/api/ivx/owner/credential-audit 2>/dev/null | bun -e '
  try {
    const d = JSON.parse(require("fs").readFileSync("/dev/stdin","utf8"));
    console.log(JSON.stringify(d, null, 2).slice(0, 500));
  } catch(e) { console.log("ERROR=" + e.message); }
' 2>/dev/null || echo "endpoint not accessible"

